      setCurrentSlide(api.selectedScrollSnap())
    }

    syncSlide()
    api.on("select", syncSlide)
    api.on("reInit", syncSlide)

    return () => {
      api.off("select", syncSlide)
      api.off("reInit", syncSlide)
    }
